import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Configuration","description":"","frontmatter":{"title":"Configuration","parent":"Installation"},"headers":[],"relativePath":"installation/config.md","filePath":"installation/config.md"}'),n={name:"installation/config.md"};function o(l,e,r,h,d,c){return s(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Fault reads configuration from <code>~/.faultrc</code> at startup. You can manage this file with the <code>fault config</code> command or edit it directly — it&#39;s a simple key=value format with <code>#</code> comments.</p><h2 id="using-fault-config" tabindex="-1">Using <code>fault config</code> <a class="header-anchor" href="#using-fault-config" aria-label="Permalink to &quot;Using `fault config`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># View current configuration</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Set solver options</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solvercmd=z3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solverarg=-in</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Set the base directory for relative file paths</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fault-host=/home/user/models</span></span></code></pre></div><p>Running <code>fault config</code> with no arguments prints the current configuration.</p><h2 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h2><h3 id="solvercmd" tabindex="-1"><code>SOLVERCMD</code> <a class="header-anchor" href="#solvercmd" aria-label="Permalink to &quot;`SOLVERCMD`&quot;">​</a></h3><p>The command used to invoke the SMT solver.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SOLVERCMD=z3</span></span></code></pre></div><p>Required for model checking. If unset, <code>fault</code> returns an error when run in <code>model</code> mode. See <a href="./solvers.html">Custom Solvers</a> for other solver options.</p><h3 id="solverarg" tabindex="-1"><code>SOLVERARG</code> <a class="header-anchor" href="#solverarg" aria-label="Permalink to &quot;`SOLVERARG`&quot;">​</a></h3><p>The argument passed to the solver to make it read SMT from stdin.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SOLVERARG=-in</span></span></code></pre></div><p>Required alongside <code>SOLVERCMD</code>.</p><h3 id="fault-host" tabindex="-1"><code>FAULT_HOST</code> <a class="header-anchor" href="#fault-host" aria-label="Permalink to &quot;`FAULT_HOST`&quot;">​</a></h3><p>The base directory that Fault uses to resolve file paths. When set, it affects three cases:</p><ul><li><strong>Relative paths</strong> — any path that doesn&#39;t start with <code>/</code> or <code>~/</code> is resolved relative to <code>FAULT_HOST</code></li><li><strong><code>..</code> segments</strong> — each <code>..</code> walks up from <code>FAULT_HOST</code>, not from the current working directory</li><li><strong><code>~</code> within a path</strong> — a <code>~</code> that appears mid-path (not at the start) is resolved relative to <code>FAULT_HOST</code> rather than your home directory</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># FAULT_HOST=</span></span></code></pre></div><p>This setting is commented out by default. Set it if your models live in a central directory and you want to reference them with short relative paths:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fault-host=/home/user/models</span></span></code></pre></div><p>Leading <code>~/</code> at the start of a file path is always expanded to your home directory, regardless of <code>FAULT_HOST</code>.</p><h2 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h2><p>All <code>~/.faultrc</code> settings can be overridden by environment variables of the same name. Environment variables take precedence over the config file.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SOLVERCMD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;z3&quot;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SOLVERARG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-in&quot;</span></span></code></pre></div><p>This is useful for CI environments or when you need per-project solver settings without modifying your global config.</p>',25)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
